CREATE OR REPLACE FUNCTION mission_generic_owner.manual_staff_template_policy_v1(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE native_proof jsonb;cfg jsonb;root mission_factory_owner.editor_release_readiness;admission jsonb;registry43 jsonb;
BEGIN
 IF p_session IS NULL THEN RETURN NULL;END IF;
 -- Existing false,false path validates sealed per-session simulation source and current
 -- Staff Root/assets. It neither authorizes a provider nor calls this policy reader.
 native_proof:=mission_generic_owner.manual_staff_native_v1(p_session,false,false);
 IF native_proof IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO root FROM mission_factory_owner.editor_release_readiness WHERE singleton;
 cfg:=root.canonical_preimage::jsonb#>'{config,c1266_manual_template}';
 -- Legacy A remains exact. Only this reviewed finite B tuple receives template ABI1.
 SELECT ma.admission INTO admission FROM mission_generic_owner.manual_staff_admissions_v1 ma
 WHERE ma.master_session_id=p_session AND ma.admission_sha256=public.combat_v2_sha256(ma.admission);
 IF admission IS NOT NULL AND admission->'source_scope' IS DISTINCT FROM cfg->'source_scope' THEN
  -- C55 is a third exact immutable source tuple; historical A/B remain separate.
  IF admission->'source_scope'=$c55scope${"PG_count":2,"PNG_count":2,"mission_id":"6d6c216a-222d-4cba-b2fc-f3e0c199c195","plan_sha256":"0066db336eb147244227104f643809eb3b3f6275277049be643a7a5b2e919e23","definition_id":"f77082bb-bb27-48b2-9b3a-8883953e79eb","source_sha256":"36a0f0e2ee9f399607cc765da1c8516ae3542d79ec9db932c8e2d2074f60ccfe","plan_version_id":"dc2202ca-2502-44cf-bd8a-52bb52f55e23","definition_sha256":"a1ac06da1f7e91cb435f017208de2da84c96f223fb73410d91d9f56b2f099a6e"}$c55scope$::jsonb THEN
   IF root.canonical_preimage::jsonb#>'{config,c1266_template_registry55}' IS DISTINCT FROM $c55registry${"scope_sha256":"6bb88ed3a8b3a0047f2e55d79b5c1233a506370d240413a910dce2e9703c3ca2"}$c55registry$::jsonb
    OR public.combat_v2_sha256(admission->'source_scope') IS DISTINCT FROM '6bb88ed3a8b3a0047f2e55d79b5c1233a506370d240413a910dce2e9703c3ca2'
   THEN RETURN NULL;END IF;
   cfg:=jsonb_set(cfg,'{source_scope}',admission->'source_scope',false);
  ELSE
  registry43:=root.canonical_preimage::jsonb#>'{config,c1266_template_registry43}';
  IF registry43 IS DISTINCT FROM '{"enabled":true,"source_scope":{"PG_count":2,"PNG_count":2,"mission_id":"6d6c216a-222d-4cba-b2fc-f3e0c199c195","plan_sha256":"015787d9ac4614de079c29313b40ff39a53864292c0b5b3b446ba19e018d022c","definition_id":"6dd07cf0-0b43-4fb8-ab2e-41da8bad85a9","source_sha256":"b20f51e697b2cb4b8f11e222bf53f399eb82e6761a04c8f093b1d6a3c77e256e","plan_version_id":"f44192bc-6a83-4def-9086-bbf4089c8fe5","definition_sha256":"79f4062d34f45a593b4a8e83d46618b479d6124cd826b63dded5a968a29ea5eb"},"financial_mode":"existing_scene_finite","schema_version":"c1266-template-registry/1"}'::jsonb
   OR admission->'source_scope' IS DISTINCT FROM registry43->'source_scope' THEN RETURN NULL;END IF;
  cfg:=jsonb_set(cfg,'{source_scope}',registry43->'source_scope',false);
  END IF;
 END IF;

 IF root.state IS DISTINCT FROM 'enabled' OR root.scope IS DISTINCT FROM 'staff'
  OR root.revision_sha256 IS DISTINCT FROM native_proof#>>'{source,release_sha256}'
  OR NOT mission_factory_owner.keys_exact_v2(cfg,ARRAY['schema_version','enabled','location_id','resource_scope','ordinary_public_enabled','source_scope','features'])
  OR cfg->>'schema_version' IS DISTINCT FROM 'c1266-manual-template-policy/1'
  OR cfg->'enabled' IS DISTINCT FROM 'true'::jsonb OR cfg->'ordinary_public_enabled' IS DISTINCT FROM 'false'::jsonb
  OR cfg->>'resource_scope' IS DISTINCT FROM 'staff_simulation'
  OR cfg->>'location_id' IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'
  OR native_proof->>'location_id' IS DISTINCT FROM cfg->>'location_id'
  OR cfg->'features' IS DISTINCT FROM '["free_narrative_v1","provider_output_retention_v1","native_intent_resolution_v1","combat_snapshot_origin_budget_v1","peaceful_route","explicit_staff_finish"]'::jsonb
  THEN RETURN NULL;END IF;
 SELECT ma.admission INTO admission FROM mission_generic_owner.manual_staff_admissions_v1 ma
 WHERE ma.master_session_id=p_session AND ma.admission_sha256=public.combat_v2_sha256(ma.admission);
 IF admission IS NULL OR admission->>'session_id' IS DISTINCT FROM p_session::text
  OR admission->'source_scope' IS DISTINCT FROM cfg->'source_scope'
  OR cfg#>>'{source_scope,source_sha256}' IS DISTINCT FROM native_proof#>>'{source,source_sha256}'
  OR cfg#>>'{source_scope,plan_version_id}' IS DISTINCT FROM native_proof#>>'{eligibility,source_plan_version_id}'
 THEN RETURN NULL;END IF;
 RETURN cfg;
END;
$function$

