import pathlib,json,copy,re,hashlib
w=pathlib.Path(__file__).parent;p=w.parent
def sha(x):return hashlib.sha256(x.encode()).hexdigest()
def js(x):return json.dumps(x,ensure_ascii=False,separators=(',',':'))
b=json.loads((p/'ROOT_BASELINE.json').read_text())[0]['baseline']['root'];r=copy.deepcopy(b['preimage']);old=copy.deepcopy(r)
f=json.loads((p/'REGISTRY_BASELINE.json').read_text())[0];ddl=f['ddl'];sig=f['signature'];scope=json.loads((w/'C_SOURCE_SCOPE.json').read_text());scopehash=json.loads((w/'C_SCOPE_HASH.json').read_text())['scope_sha256']
before=copy.deepcopy(next(h for h in r['db_core']['all_function_headers'] if h['signature']==sig))
assert hashlib.md5(ddl.encode()).hexdigest()==before['ddl_md5'] and hashlib.md5(re.search(r'AS \$function\$(.*?)\$function\$',ddl,re.S).group(1).encode()).hexdigest()==before['source_md5']==f['md5']
assert scope['plan_version_id']=='dc2202ca-2502-44cf-bd8a-52bb52f55e23' and scope['PG_count']==scope['PNG_count']==2
registry={'scope_sha256':scopehash}
needle="  registry43:=root.canonical_preimage::jsonb#>'{config,c1266_template_registry43}';"
assert ddl.count(needle)==1
prefix="""  -- C55 is a third exact immutable source tuple; historical A/B remain separate.
  IF admission->'source_scope'=$c55scope$@@SCOPE@@$c55scope$::jsonb THEN
   IF root.canonical_preimage::jsonb#>'{config,c1266_template_registry55}' IS DISTINCT FROM $c55registry$@@REGISTRY@@$c55registry$::jsonb
    OR public.combat_v2_sha256(admission->'source_scope') IS DISTINCT FROM '@@HASH@@'
   THEN RETURN NULL;END IF;
   cfg:=jsonb_set(cfg,'{source_scope}',admission->'source_scope',false);
  ELSE
""".replace('@@SCOPE@@',js(scope)).replace('@@REGISTRY@@',js(registry)).replace('@@HASH@@',scopehash)
afterddl=ddl.replace(needle,prefix+needle)
tail="  cfg:=jsonb_set(cfg,'{source_scope}',registry43->'source_scope',false);\n END IF;"
assert afterddl.count(tail)==1;afterddl=afterddl.replace(tail,tail.replace('\n END IF;','\n  END IF;\n END IF;'))
# Historical B branch is byte-identical between ELSE and its added END IF.
oldbranch=ddl[ddl.index(needle):ddl.index(tail)+len(tail)-len('\n END IF;')]
assert oldbranch in afterddl and "cfg:=root.canonical_preimage::jsonb#>'{config,c1266_manual_template}';" in afterddl
after=copy.deepcopy(before);after['source_md5']=hashlib.md5(re.search(r'AS \$function\$(.*?)\$function\$',afterddl,re.S).group(1).encode()).hexdigest();after['ddl_md5']=hashlib.md5(afterddl.encode()).hexdigest()
paths=[]
def walk(x,path=''):
 if isinstance(x,dict):
  if x.get('oid')==before['oid']:
   assert x['source_md5']==before['source_md5'] and x['ddl_md5']==before['ddl_md5'];x['source_md5']=after['source_md5'];x['ddl_md5']=after['ddl_md5'];paths.append(path)
  for k,v in x.items():walk(v,path+'/'+k)
 elif isinstance(x,list):
  for i,v in enumerate(x):walk(v,path+'/'+str(i))
walk(r)
r['config']['c1266_template_registry55']=registry
r['db_core']['migration_id']='c1266_registry55_exact_C'
r['contract']['code_identity_sha256']=sha(js({'predecessor_root':b['header']['revision_sha256'],'source_ddl_sha256':sha(afterddl),'source_scope':scope,'registry':registry}))
assert {k:v for k,v in r['config'].items() if k!='c1266_template_registry55'}==old['config']
assert r['edge_bundles']==old['edge_bundles'] and r['ui']==old['ui'] and r['recovery']==old['recovery']
text=js(r);newsha=sha(text);assert len(text.encode())<=262144
preserve="""SELECT jsonb_build_object('sessions',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.master_v2_sessions x WHERE id IN('1fb789a2-0319-435f-9f6d-dd517cac7cd3','4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4')),'fati',(SELECT jsonb_agg(jsonb_build_object('id',m.id,'body_sha256',encode(extensions.digest(convert_to(m.body,'UTF8'),'sha256'),'hex')) ORDER BY m.id) FROM public.messages m WHERE m.id IN(SELECT message_id FROM mission_generic_owner.work_items WHERE master_session_id IN('1fb789a2-0319-435f-9f6d-dd517cac7cd3','4c7b05e0-b5b7-4586-9aa9-2a77ae03deb4')) AND kind='fato'))"""
hcheck="""FOR h IN SELECT value FROM jsonb_array_elements(EXPECTED#>'{db_core,all_function_headers}') LOOP
 SELECT p.oid::bigint AS oid,pg_get_userbyid(p.proowner) AS owner,p.proacl::text AS acl,to_jsonb(p.proconfig) AS config,p.prosecdef AS secdef,p.provolatile::text AS volatility,l.lanname AS language,md5(p.prosrc) AS source_md5,md5(pg_get_functiondef(p.oid)) AS ddl_md5 INTO pr FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(h->>'signature');
 IF NOT FOUND OR to_jsonb(pr) IS DISTINCT FROM h-'signature' THEN RAISE EXCEPTION 'C55_ABI_DRIFT %',h->>'signature';END IF;
END LOOP;"""
sql="""DO $registry55$
DECLARE rr mission_factory_owner.editor_release_readiness;candidate text:=$candidate$@@TEXT@@$candidate$;h jsonb;pr record;before_data jsonb;after_data jsonb;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'C55_OWNER_REQUIRED';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0)) THEN RAISE EXCEPTION 'C55_RELEASE_BUSY';END IF;
 SELECT * INTO STRICT rr FROM mission_factory_owner.editor_release_readiness WHERE singleton FOR UPDATE NOWAIT;
 IF rr.canonical_preimage IS DISTINCT FROM $old$@@OLDTEXT@@$old$ OR to_jsonb(rr)-'canonical_preimage' IS DISTINCT FROM $header$@@HEADER@@$header$::jsonb THEN RAISE EXCEPTION 'C55_ROOT_DRIFT';END IF;
 IF EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE state IN('claimed','authorized','provider_started')) THEN RAISE EXCEPTION 'C55_PROVIDER_ACTIVE';END IF;
 IF EXISTS(SELECT 1 FROM public.master_v2_sessions m WHERE m.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b' AND m.closed_at IS NULL) THEN RAISE EXCEPTION 'C55_STAFF_IN_USE';END IF;
 @@CHECK_BEFORE@@
 @@PRESERVE@@ INTO before_data;
 EXECUTE $patch$@@DDL@@$patch$;
 @@CHECK_AFTER@@
 IF candidate::jsonb#>'{config,c1266_template_registry43}' IS DISTINCT FROM rr.canonical_preimage::jsonb#>'{config,c1266_template_registry43}'
 OR candidate::jsonb#>'{config,c1266_manual_template}' IS DISTINCT FROM rr.canonical_preimage::jsonb#>'{config,c1266_manual_template}'
 OR candidate::jsonb->'edge_bundles' IS DISTINCT FROM rr.canonical_preimage::jsonb->'edge_bundles'
 OR candidate::jsonb->'ui' IS DISTINCT FROM rr.canonical_preimage::jsonb->'ui'
 OR octet_length(candidate)>262144 OR encode(extensions.digest(convert_to(candidate,'UTF8'),'sha256'),'hex') IS DISTINCT FROM '@@NEW@@'
 THEN RAISE EXCEPTION 'C55_COMPOSITION_INVALID';END IF;
 UPDATE mission_factory_owner.editor_release_readiness SET canonical_preimage=candidate,revision_sha256='@@NEW@@',observed_revision_sha256='@@NEW@@',client_build='mission-factory-admin/2:@@NEW@@',independent_review_ref='C1266_THIRD55_REVIEW.json',updated_at=clock_timestamp() WHERE singleton AND revision_sha256='@@OLD@@' AND canonical_preimage=rr.canonical_preimage;
 IF NOT FOUND THEN RAISE EXCEPTION 'C55_ROOT_CAS_LOST';END IF;
 @@PRESERVE@@ INTO after_data;
 IF before_data IS DISTINCT FROM after_data THEN RAISE EXCEPTION 'C55_HISTORY_MUTATED';END IF;
END
$registry55$;
"""
vals={'TEXT':text,'OLDTEXT':b['text'],'HEADER':js(b['header']),'OLD':b['header']['revision_sha256'],'NEW':newsha,'CHECK_BEFORE':hcheck.replace('EXPECTED','rr.canonical_preimage::jsonb'),'CHECK_AFTER':hcheck.replace('EXPECTED','candidate::jsonb'),'PRESERVE':preserve,'DDL':afterddl}
