assert all(checks.values())
manifest={'status':'SOURCE_CANDIDATE_NOT_REVIEWED_NOT_APPLIED','baseline_root':b['header']['revision_sha256'],'candidate_root':newsha,'root_bytes':len(text.encode()),'root_byte_cap':262144,'root_remaining_bytes':262144-len(text.encode()),'function_signature':sig,'before_header':before,'after_header':after,'updated_header_paths':paths,'source_scope':scope,'source_scope_sha256':scopehash,'registry':registry,'edge_version_unchanged':117,'new_function':False,'new_constraints':[],'relaxed_constraints':[],'operational_amendment':'Only exact C source additionally eligible under existing manual Staff template; existing authentication, Staff, source, resource, roster and provider guards remain. No session or provider admission created.','static_checks':checks,'source_sha256':sha(afterddl),'installer_sha256':sha(sql),'installer_bytes':len(sql.encode()),'budget':json.loads((p/'BUDGET.json').read_text()),'budget_apply':'No budget/counter/window/table mutation in installer; parent must bind finite assistant budget via existing authorized route before starting C.'}
(w/'MANIFEST.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:manifest[k] for k in ['candidate_root','root_bytes','root_remaining_bytes','source_sha256','installer_sha256','installer_bytes','updated_header_paths']}))

